<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {api} from '../lib/api'
import {formatGameTime} from '../lib/gameTime'
const game=ref('cards'),level=ref(1),search=ref(''),status=ref('active'),result=ref({items:[],total:0,page:1,pages:1}),loading=ref(false),working=ref(false),error=ref(''),notice=ref(''),dialog=ref(null),target=ref(null),confirm=ref(''),applied=ref({game:'cards',level:1,search:'',status:'active'});let alive=true,request=0
const gameName=computed(()=>game.value==='cards'?'카드 뒤집기':'숨은그림 찾기'),levelCount=computed(()=>game.value==='cards'?8:10)
function filters(){return {game:game.value,level:level.value,search:search.value.trim(),status:status.value}}
async function load(page=1){const current=++request,query=filters();loading.value=true;error.value='';try{const value=await api('/admin/game-rankings?'+new URLSearchParams({...query,page}));if(alive&&current===request){result.value=value;applied.value=query}}catch(e){if(alive&&current===request)error.value=e.message}finally{if(alive&&current===request)loading.value=false}}
function ask(row=null){if(loading.value||working.value)return;target.value=row;confirm.value='';error.value='';dialog.value.showModal()}
function close(){if(!working.value)dialog.value.close()}
async function remove(){if(working.value||!target.value&&confirm.value!=='삭제')return;working.value=true;error.value='';try{const response=target.value?await api('/admin/game-rankings/'+target.value.game+'/'+target.value.sessionId,{method:'DELETE'}):await api('/admin/game-rankings',{method:'DELETE',body:{...applied.value,confirm:confirm.value}});if(!alive)return;dialog.value.close();notice.value=response.changed+'개 기록을 명예의 전당에서 삭제했어요.';await load(result.value.page)}catch(e){if(alive)error.value=e.message}finally{if(alive)working.value=false}}
async function restore(row){if(working.value||loading.value)return;working.value=true;error.value='';try{await api('/admin/game-rankings/'+row.game+'/'+row.sessionId+'/restore',{method:'POST',body:{}});if(alive){notice.value='게임 기록을 복원했어요.';await load(result.value.page)}}catch(e){if(alive)error.value=e.message}finally{if(alive)working.value=false}}
onMounted(()=>load());onUnmounted(()=>{alive=false;request++;dialog.value?.close()})
</script>
<template><section class="panel admin-game-records"><h2>🏆 명예의 전당 기록 관리</h2><p>잘못된 기록을 순위에서 제외하고, 삭제된 기록은 다시 복원할 수 있어요. 지급된 포인트와 게임 클리어 기록은 보존됩니다.</p><form @submit.prevent="load()"><fieldset class="record-filters" :disabled="loading||working"><label>게임<select v-model="game" @change="level=1;load()"><option value="cards">카드 뒤집기</option><option value="hidden">숨은그림 찾기</option></select></label><label>단계<select v-model.number="level" @change="load()"><option v-for="n in levelCount" :key="n" :value="n">{{n}}단계</option></select></label><label>학생 검색<input v-model="search" maxlength="100" placeholder="이름 또는 아이디"/></label><label>기록 상태<select v-model="status" @change="load()"><option value="active">현재 기록</option><option value="deleted">삭제된 기록</option></select></label><button>검색·새로고침</button></fieldset></form><div class="record-heading"><b>{{gameName}} · {{level}}단계 · {{result.total}}개</b><button v-if="status==='active'" class="danger-button" :disabled="loading||working||!result.total" @click="ask()">검색 결과 전체 삭제</button></div><p v-if="notice" role="status">{{notice}}</p><p v-if="error&&!dialog?.open" role="alert">{{error}}</p><p v-if="loading" role="status">기록을 불러오는 중…</p><p v-else-if="!result.items.length">해당하는 게임 기록이 없어요.</p><div v-else class="game-record-table"><table><thead><tr><th>학생</th><th>기수</th><th>완료 시간</th><th>{{game==='cards'?'시도':'실수 / 힌트'}}</th><th>플레이 일시</th><th>관리</th></tr></thead><tbody><tr v-for="row in result.items" :key="row.sessionId"><td><b>{{row.nickname}}</b><small>@{{row.login}}</small></td><td>{{row.className}}</td><td>{{formatGameTime(row.durationMs)}}</td><td>{{row.attempts}}{{game==='hidden'?' / '+row.hints:''}}</td><td>{{new Date(row.completedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</td><td><button v-if="status==='active'" class="danger-button" :disabled="working||loading" @click="ask(row)">기록 삭제</button><button v-else class="light" :disabled="working||loading" @click="restore(row)">복원</button></td></tr></tbody></table></div><nav v-if="result.pages>1" class="record-pagination" aria-label="게임 기록 페이지"><button class="light" :disabled="loading||working||result.page<=1" @click="load(result.page-1)">이전</button><span>{{result.page}} / {{result.pages}}</span><button class="light" :disabled="loading||working||result.page>=result.pages" @click="load(result.page+1)">다음</button></nav><dialog ref="dialog" class="records-confirm" aria-labelledby="record-delete-title" @cancel.prevent="close"><h2 id="record-delete-title">{{target?'이 기록을 삭제할까요?':'검색 결과를 모두 삭제할까요?'}}</h2><p>{{gameName}} · {{level}}단계</p><p v-if="target"><b>{{target.nickname}}</b> (@{{target.login}}) · {{formatGameTime(target.durationMs)}}</p><template v-else><p><b>{{applied.search?'학생 검색: '+applied.search:'전체 학생'}}</b> · 현재 조건의 기록 {{result.total}}개</p><label for="record-delete-confirm">확인을 위해 ‘삭제’를 입력하세요.</label><input id="record-delete-confirm" v-model="confirm" :disabled="working" autocomplete="off"/></template><p>명예의 전당에서 제외되며 ‘삭제된 기록’에서 복원할 수 있어요. 보상 포인트는 차감되지 않습니다.</p><p v-if="error" role="alert">{{error}}</p><div class="toolbar"><button class="light" :disabled="working" @click="close">취소</button><button class="danger-button" :disabled="working||!target&&confirm!=='삭제'" @click="remove">{{working?'처리 중…':'삭제 확정'}}</button></div></dialog></section></template>
<style scoped>
.admin-game-records>p{font-size:12px;line-height:1.8}.record-filters{display:flex;gap:12px;flex-wrap:wrap;align-items:end;border:0;padding:0;margin:18px 0}.record-filters label{display:grid;gap:7px;flex:1;min-width:130px;font-size:12px}.record-filters input,.record-filters select{width:100%;min-width:0;box-sizing:border-box}.record-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:16px 0}.game-record-table{overflow:auto;max-height:520px}.game-record-table table{width:100%;border-collapse:collapse;min-width:650px}.game-record-table th,.game-record-table td{padding:12px 9px;text-align:left;border-bottom:1px solid var(--rpg-mid);font-size:12px}.game-record-table th{position:sticky;top:0;background:var(--rpg-soft);z-index:1}.game-record-table small{display:block;margin-top:5px}.record-pagination{display:flex;gap:14px;align-items:center;justify-content:center;margin-top:16px}.records-confirm{box-sizing:border-box;width:min(520px,calc(100vw - 28px));max-height:90dvh;overflow:auto;padding:24px;border:3px solid var(--rpg-edge);border-radius:14px;background:var(--rpg-paper);color:var(--rpg-ink)}.records-confirm::backdrop{background:#152337aa}.records-confirm h2{font-size:21px}.records-confirm p{font-size:12px;line-height:1.8}.records-confirm input{display:block;width:100%;box-sizing:border-box;margin:9px 0}.records-confirm .toolbar{flex-wrap:wrap}@media(max-width:600px){.record-filters label{min-width:calc(50% - 12px)}.record-filters button{width:100%}.records-confirm{padding:18px}}
</style>
